tructions", "qualifiers": {"version": null, "event_date": null, "place": null, "counterparty": "Gate, MEXC, Binance, OKX, Rubic"}, "origin": "own", "source_role": "author", "verification_status": "unverified", "quote": "🔔 Что делаем:
